def choose_move(observation):
    def clamp_step(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def to_pair(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, int) and isinstance(b, int):
                return a, b
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_score(items, score_fn):
        best_item = None
        best_score = None
        for it in items:
            try:
                sc = score_fn(it)
            except Exception:
                continue
            if best_item is None or sc < best_score:
                best_item = it
                best_score = sc
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = to_pair(observation.get("self_position", (0, 0)))
    ox, oy = to_pair(observation.get("opponent_position", (sx, sy)))
    s = (sx, sy)
    o = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(s, o)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by_score(corners, lambda c: -dist(c, o))
        if target is None:
            return step_away(s, o)
        return step_toward(s, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_by_score(targets, lambda c: dist(s, to_pair(c)))
        if target is None:
            return step_away(s, o) if dist(s, o) <= 2 else [0, 0]
        t = to_pair(target)
        move = step_toward(s, t)
        if dist(s, o) <= 1 and move == step_toward(s, o):
            return step_away(s, o)
        return move

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_score(resources, lambda c: dist(s, to_pair(c)) + (1 if dist(o, to_pair(c)) < dist(s, to_pair(c)) else 0))
    if target is not None:
        t = to_pair(target)
        move = step_toward(s, t)
        if dist(s, o) <= 1 and move == step_toward(s, o):
            return step_away(s, o)
        return move

    return step_away(s, o) if dist(s, o) <= 2 else [0, 0]

